-- Full Spectrum grants: batch 5 (funder pages read 2026-11-01).
-- 9 new funders. Walmart Spark Good was already on the tracker (FY27 Cycle 3 submitted), so it is not re-added. Idempotent.
-- Apply: supabase db query --linked -f supabase/fs-grants-batch5.sql
begin;
select count(*) as before_total from fs_grant_deadlines;

insert into fs_grant_deadlines (funder, program, kind, deadline_date, opens_date, amount, verified, url, notes, verified_on, level, project, priority, eligibility, match_required, status, gates, next_step, next_step_due)
select * from (values
('Aerie Real Foundation','Community Grants','rolling',null::date,null::date,'up to $10,000',true,'https://blog.aerie.com/aerie-real-foundation-grant-guidelines/','Rolling, online portal. 501(c)(3) with a specific project building confidence in women. New organizations may give PROJECTED expenses instead of three years of budgets. Pitch the weekly guest woman DJ and mentorship (women teaching, leading sets, performing at Rainbow Wednesdays). Do NOT pitch a girls-only track: the DJ Lab is one class for everyone. Confirm how the women-focused criteria apply.','2026-11-01'::date,'corporate','djclass',1,'501(c)(3); project builds confidence in women; new orgs may use projected budgets',null,'to_research','{g0}'::text[],'Draft the guest woman DJ mentorship project and projected budget, then apply through the portal',null::date),
('U.S. Bank Foundation','Community Possible: Play Grants (letter of interest)','rolling',null,null,'not published',true,'https://www.usbank.com/about-us-bank/community/community-possible-grant-program/play-grants.html','New organizations submit a LETTER OF INTEREST any time of year; a full application is by invitation only. Funds arts education and access to arts. Must serve a designated U.S. Bank community. Official Submit letter of interest link; usbankfoundation@usbank.com.','2026-11-01'::date,'corporate','djclass',1,'501(c)(3) serving a U.S. Bank community; invitation for full application',null,'to_research','{g0}'::text[],'Confirm Chicago is a U.S. Bank community and send the letter of interest',null),
('7-Eleven','Project A-Game (franchise owner champion)','relationship',null,null,'not published',true,'https://corp.7-eleven.com/corp/project-a-game','Youth education grants co-funded by a franchise owner and the foundation. THE FRANCHISEE APPLIES, not Ras Tafari. Includes local educational programs, not only Boys & Girls Clubs. No deadline or amount on the page. Step one is finding a nearby franchise owner willing to champion free DJ instruction.','2026-11-01'::date,'corporate','djclass',3,'Needs a franchise owner champion',null,'to_research','{g4}'::text[],'Ask the nearest 7-Eleven owners near Rainbow Beach / South Shore whether they would champion the DJ Lab',null),
('PNC','Charitable Sponsorships','relationship',null,null,'not published',true,'https://www.pnc.com/en/about-pnc/corporate-responsibility/philanthropy/charitable-sponsorships.html','Sponsors arts and culture; Cook County eligible. Complete the eligibility quiz, then contact Chicago representative Craig Esko, craig.esko@pnc.com, 312-338-2236, for timing and requirements. No amount or deadline published. Pitch Rainbow Wednesdays: free neighborhood programming that pays local artists.','2026-11-01'::date,'corporate','wednesdays',2,'Eligibility quiz; Cook County eligible',null,'to_research','{g0}'::text[],'Take the eligibility quiz and email the Chicago rep about 2027 sponsorship timing',null),
('Huntington Bank','Community Giving (grants invitation-only; sponsorships)','relationship',null,null,'not published',true,'https://www.huntington.com/Community/giving-guidelines','Formal grants are INVITATION-ONLY, reviewed quarterly; get a community-development introduction first. Focus: youth programs and digital inclusion where 50%+ of participants are low or moderate income (document it). Illinois regional marketing contact for sponsorships: Saul Boscan, saul.boscan@huntington.com. Confirm a Huntington presence in Chicago.','2026-11-01'::date,'corporate','djclass',3,'Invitation-only grants; 50%+ low-to-moderate-income participants',null,'to_research','{g0,g4}'::text[],'Email the regional contact about an introduction and sponsorship timing',null),
('Oak Park-River Forest Community Foundation','Carlos Baldoceda Memorial Scholarship','paused',null,null,'up to $1,000 per person',true,'https://oprfcf.org/enrichment-grants/','For an individual young musician (Chicago-area residents 14-25): equipment, materials, instruction. Last cycle closed; page said check back fall 2026. Ask grantservices@oprfcf.org for the opening and whether DJ equipment qualifies. Student support, not an organizational grant.','2026-11-01'::date,'foundation','djclass',3,'Individual Chicago-area musicians 14-25; not organizations',null,'not_eligible','{}'::text[],'Email grantservices@oprfcf.org for the current opening; tell eligible students',null),
('Casey''s','Cash for Classrooms','dated','2026-11-13'::date,'2026-10-12'::date,'not published',true,'https://www.caseys.com/community/cash-for-classrooms-grants','2027 applications opened Oct 12, close Nov 13 2026. For K-12 public and nonprofit private schools in the Casey''s footprint: A SCHOOL applies, not Ras Tafari, and this is not a direct grant for the beach series. Footprint is mostly the Midwest outside big cities: check Chicago-area eligibility first. Press release has an inconsistent award year: confirm timing.','2026-11-01'::date,'corporate','djclass',3,'K-12 school in a Casey''s service area applies',null,'to_research','{g4}'::text[],'Probably skip: confirm a partner school is in the Casey''s footprint before Nov 13',null),
('Youth Service America (Hershey)','Heartwarming Young Heroes','paused',null,null,'$250, $500 or $1,000',true,'https://ysa.org/grants/hershey/','Last deadline was Mar 15 2026; no 2027 date yet. Youth ages 5-25 lead a community SERVICE project (a class or party alone does not qualify). Idea: students design a neighborhood-pride arts and music service project. Questions: sganske@ysa.org.','2026-11-01'::date,'foundation','wednesdays',3,'Youth 5-25 lead a service project',null,'to_research','{}'::text[],'Watch for the 2027 cycle (check March)',null),
('Paul M. Angell Family Foundation','Performing Arts (expression of interest)','relationship',null,null,'not published',true,'https://paulangell.org/performing-arts','Applications closed, but a 200-word expression of interest may be sent to performingarts@paulangell.org; an invitation precedes a full application. The separate 2026 new-work competition (July deadline) has passed. Fit is for an artist-led performance project, not the DJ Lab itself.','2026-11-01'::date,'foundation','selassiefest',3,'Invitation after expression of interest',null,'to_research','{g1}'::text[],'Decide if an original-music performance project fits, then send the 200-word expression of interest',null)
) as v(funder,program,kind,deadline_date,opens_date,amount,verified,url,notes,verified_on,level,project,priority,eligibility,match_required,status,gates,next_step,next_step_due)
where not exists (select 1 from fs_grant_deadlines g where g.funder = v.funder and g.program = v.program);

select count(*) as after_total from fs_grant_deadlines;
commit;
